grant masarifi_migration to current_user with set true, inherit false;
set local role masarifi_migration;

-- Generated from the repository rule asset after deterministic corpus checks.
-- Published releases remain immutable; a new release preserves rollback.
insert into public.tracking_rule_releases(id,schema_version,engine_version,status,snapshot,content_hash,validated_hash,corpus_result,created_by,published_by,published_at,reason)
select '20000000-0000-4000-8000-000000000003',2,'2.0.0','published',v,
  encode(extensions.digest(convert_to(v::text,'UTF8'),'sha256'),'hex'),
  encode(extensions.digest(convert_to(v::text,'UTF8'),'sha256'),'hex'),
