on conflict ((snapshot->>'releaseId')) do nothing;

insert into public.tracking_rule_entries(release_id,rule_key,family,enabled,priority,definition)
select r.id,e->>'ruleKey',e->>'family',(e->>'enabled')::boolean,(e->>'priority')::integer,e
from public.tracking_rule_releases r cross join lateral jsonb_array_elements(r.snapshot->'rules') e
where r.snapshot->>'releaseId'='bundled-sa-ae-eg-2026-10-09'
on conflict do nothing;

-- Upgrade the bundled baseline only; never replace an administrator's newer
-- published catalog. Start in review until scoped acceptance enables posting.
update public.tracking_rule_channels c set release_id=r.id,mode='review',version=c.version+1,updated_at=clock_timestamp()
from public.tracking_rule_releases r, public.tracking_rule_releases prior
where c.release_id=prior.id and prior.snapshot->>'releaseId'='bundled-sa-ae-2026-10-09'
  and r.snapshot->>'releaseId'='bundled-sa-ae-eg-2026-10-09'
  and c.environment='default' and c.market='global' and c.channel='all';

-- The existing unique phrase key and seed preserve disabled/default/custom
-- rows, IDs and versions, while backfilling new words for existing owners.
select private.seed_default_keyword_rules(id) from public.profiles where status='active';

reset role;
revoke masarifi_migration from current_user granted by current_user;
